@SpringBootTest(classes=BackendApplication.class)
class EmployabilityPlanPostgresTest {
 @Autowired EmployabilityPlanService plans;@Autowired RadarService radar;@Autowired RadarBridge bridge;@Autowired JdbcTemplate jdbc;@Autowired WebApplicationContext context;@Autowired TrailTokenService tokens;
 com.sun.net.httpserver.HttpServer server;Object oldBase,oldSecret;AtomicReference<String> training=new AtomicReference<>();AtomicBoolean fail=new AtomicBoolean();AtomicReference<CountDownLatch> gate=new AtomicReference<>();CountDownLatch called;
 record User(long id,String email){}
 @BeforeEach void source()throws Exception{
  oldBase=ReflectionTestUtils.getField(bridge,"base");oldSecret=ReflectionTestUtils.getField(bridge,"secret");training.set(bridge.encode(List.of(Map.of("course_id",17,"module_id",8,"course_title","Curso sintético da fonte de teste","module_title","SQL de teste","skill_code","sql","level",2))));called=new CountDownLatch(1);
  server=com.sun.net.httpserver.HttpServer.create(new java.net.InetSocketAddress("127.0.0.1",0),0);
  server.createContext("/api/",exchange->{String body="[]";if(fail.get()){exchange.sendResponseHeaders(503,-1);exchange.close();return;}if(exchange.getRequestURI().getPath().endsWith("/training")){called.countDown();try{var wait=gate.get();if(wait!=null&&!wait.await(4,TimeUnit.SECONDS))throw new IllegalStateException();}catch(Exception e){exchange.close();return;}body=training.get();}else if(exchange.getRequestURI().getPath().endsWith("/radar-jobs"))body="{\"items\":[],\"nextCursor\":null}";byte[] bytes=body.getBytes(java.nio.charset.StandardCharsets.UTF_8);exchange.getResponseHeaders().add("Content-Type","application/json");exchange.sendResponseHeaders(200,bytes.length);exchange.getResponseBody().write(bytes);exchange.close();});server.start();
  ReflectionTestUtils.setField(bridge,"base","http://127.0.0.1:"+server.getAddress().getPort()+"/api");ReflectionTestUtils.setField(bridge,"secret","synthetic-plan-bridge-secret-0000000000");
 }
 @AfterEach void restore(){var wait=gate.get();if(wait!=null)wait.countDown();server.stop(0);ReflectionTestUtils.setField(bridge,"base",oldBase);ReflectionTestUtils.setField(bridge,"secret",oldSecret);}
 User user(){String email=UUID.randomUUID()+"@example.test";long id=jdbc.queryForObject("INSERT INTO app_users(email,password_hash,full_name,email_verified,account_type) VALUES (?,'synthetic','Pessoa de teste',TRUE,'PERSON') RETURNING id",Long.class,email);return new User(id,email);}
 long job(){long id=jdbc.queryForObject("INSERT INTO catalog_items(kind,title,provider,description,url,area,active,moderation_status) VALUES ('job','Analista sintético','Fonte de teste','Fixture','https://example.test','technology',TRUE,'APPROVED') RETURNING id",Long.class);var need=new RadarModel.Requirements(1,List.of(new RadarModel.Need("sql",2,true,false,false)),null,null,false,false,"","","");jdbc.update("INSERT INTO radar_catalog_requirements(item_id,revision,definition) VALUES (?,1,?::jsonb)",id,bridge.encode(need));return id;}
 Objectives goal(long job){return new Objectives("Objetivo de teste","","","",List.of(),List.of(new JobRef("catalog",job)));}
 long revision(User u){return ((Number)plans.get(u.email()).get("revision")).longValue();}
 Map<String,Object> generate(User u){return map(plans.refresh(u.email(),new Refresh(revision(u),UUID.randomUUID())).get("plan"));}
 List<Map<String,Object>> steps(User u){return rows(map(plans.get(u.email()).get("snapshot")).get("steps"));}
 void status(int expected,Runnable run){assertEquals(expected,assertThrows(ResponseStatusException.class,run::run).getStatusCode().value());}
 @Test void generatesRealReferencesTransparentGapsAndNoDuplicateTraining(){var u=user();assertEquals(false,plans.get(u.email()).get("exists"));plans.update(u.email(),new Update(goal(job()),0L));var plan=generate(u);var snapshot=map(plan.get("snapshot"));assertEquals(1,rows(snapshot.get("analyses")).size());assertEquals(1,steps(u).stream().filter(s->"TRAINING".equals(s.get("kind"))).count());assertTrue(steps(u).stream().allMatch(s->s.containsKey("criteria")&&s.containsKey("criterionHash")));assertEquals("SNAPSHOT_NOT_LIVE",plan.get("sourceFreshness"));}
 @Test void goalsCanExistWithoutJobsOrCourses(){var u=user();training.set("[]");plans.update(u.email(),new Update(new Objectives("Objetivo sem oferta","","","",List.of(new SkillGoal("sql",2,false)),List.of()),0L));var plan=generate(u);assertTrue(steps(u).stream().noneMatch(s->"TRAINING".equals(s.get("kind"))));assertTrue(steps(u).stream().anyMatch(s->"SKILL_DEVELOPMENT".equals(s.get("kind"))));assertTrue(rows(map(plan.get("snapshot")).get("analyses")).stream().noneMatch(a->a.containsKey("job")));}
 @Test void declaredSkillsAreNotVerifiedEvidenceAndDiagnosticIsNotAProficiencyScore(){var u=user();radar.declare(u.email(),new RadarService.Declaration("sql",2));jdbc.update("UPDATE app_users SET diagnostic_data=? WHERE id=?",bridge.encode(Map.of("trackId","technology","trackName","Tecnologia","answers",Collections.nCopies(10,1),"scores",Map.of("technology",99))),u.id());plans.update(u.email(),new Update(new Objectives("Meta","","","",List.of(new SkillGoal("sql",2,false)),List.of()),0L));generate(u);assertTrue(steps(u).stream().noneMatch(s->"SKILL_DEVELOPMENT".equals(s.get("kind"))));plans.update(u.email(),new Update(new Objectives("Meta","","","",List.of(new SkillGoal("sql",2,true)),List.of()),revision(u)));generate(u);assertTrue(steps(u).stream().anyMatch(s->"SKILL_DEVELOPMENT".equals(s.get("kind"))));assertTrue(steps(u).stream().noneMatch(s->"DIAGNOSTIC".equals(s.get("kind"))));}
 @Test void progressSurvivesSameCriteriaAndResetsWhenLevelChanges(){var u=user();plans.update(u.email(),new Update(new Objectives("Meta","","","",List.of(new SkillGoal("sql",2,false)),List.of()),0L));generate(u);var step=steps(u).stream().filter(s->"SKILL_DEVELOPMENT".equals(s.get("kind"))).findFirst().orElseThrow();String key=step.get("key").toString();plans.progress(u.email(),key,new Progress("DECLARED_DONE",revision(u)));generate(u);assertEquals("DECLARED_DONE",rows(plans.get(u.email()).get("progress")).stream().filter(p->p.get("step_key").equals(key)).findFirst().orElseThrow().get("state"));plans.update(u.email(),new Update(new Objectives("Meta revisada","","","",List.of(new SkillGoal("sql",3,false)),List.of()),revision(u)));assertNull(plans.get(u.email()).get("snapshot"));generate(u);assertEquals("NOT_STARTED",rows(plans.get(u.email()).get("progress")).stream().filter(p->p.get("step_key").equals(key)).findFirst().orElseThrow().get("state"));}
 @Test void refreshIsIdempotentAndInputsInvalidateStaleProgress(){var u=user();plans.update(u.email(),new Update(goal(job()),0L));var input=new Refresh(1L,UUID.randomUUID());plans.refresh(u.email(),input);assertEquals(true,plans.refresh(u.email(),input).get("replayed"));assertEquals(1,rows(plans.history(u.email(),Long.MAX_VALUE,20).get("items")).size());radar.declare(u.email(),new RadarService.Declaration("sql",1));assertEquals(true,plans.get(u.email()).get("localInputsChanged"));String key=steps(u).getFirst().get("key").toString();status(409,()->plans.progress(u.email(),key,new Progress("DECLARED_DONE",revision(u))));status(409,()->plans.refresh(u.email(),new Refresh(0L,UUID.randomUUID())));}
 @Test void expiredJobsAndUnavailableSourcesAreExplicitWithoutInventedOffers(){var u=user();long id=job();jdbc.update("UPDATE catalog_items SET active=FALSE WHERE id=?",id);fail.set(true);plans.update(u.email(),new Update(goal(id),0L));var snapshot=map(generate(u).get("snapshot"));assertTrue(rows(snapshot.get("analyses")).isEmpty());assertEquals(true,snapshot.get("partial"));assertTrue(steps(u).stream().noneMatch(s->"TRAINING".equals(s.get("kind"))));}
 @Test void foreignProgressAndUnverifiedUsersCannotBeUsed(){var a=user();var b=user();plans.update(a.email(),new Update(new Objectives("Objetivo exclusivo "+UUID.randomUUID(),"","","",List.of(new SkillGoal("java",2,false)),List.of()),0L));plans.update(b.email(),new Update(new Objectives("Objetivo exclusivo "+UUID.randomUUID(),"","","",List.of(new SkillGoal("sql",2,false)),List.of()),0L));generate(a);generate(b);String foreign=steps(b).stream().filter(s->"SKILL_DEVELOPMENT".equals(s.get("kind"))).findFirst().orElseThrow().get("key").toString();assertTrue(steps(a).stream().noneMatch(step->foreign.equals(step.get("key"))));status(404,()->plans.progress(a.email(),foreign,new Progress("DECLARED_DONE",revision(a))));assertEquals(0L,plans.get(b.email()).get("declaredDone"));jdbc.update("UPDATE app_users SET email_verified=FALSE WHERE id=?",a.id());status(403,()->plans.get(a.email()));}
 @Test void concurrentGoalChangeRejectsTheInFlightGeneration()throws Exception{var u=user();plans.update(u.email(),new Update(goal(job()),0L));var block=new CountDownLatch(1);gate.set(block);try(var pool=Executors.newSingleThreadExecutor()){var pending=pool.submit(()->{try{plans.refresh(u.email(),new Refresh(1L,UUID.randomUUID()));return 200;}catch(ResponseStatusException e){return e.getStatusCode().value();}});assertTrue(called.await(5,TimeUnit.SECONDS));plans.update(u.email(),new Update(new Objectives("Novo objetivo","","","",List.of(),List.of()),1L));block.countDown();assertEquals(409,pending.get(10,TimeUnit.SECONDS));assertNull(plans.get(u.email()).get("snapshot"));}finally{block.countDown();}}
 @Test void privateHttpEndpointsUseOnlyTheOportunidadesSession()throws Exception{var u=user();var mvc=MockMvcBuilders.webAppContextSetup(context).apply(SecurityMockMvcConfigurers.springSecurity()).build();String token=tokens.issue(TrailTokenService.Trail.OPORTUNIDADES,u.email(),u.id(),0);var payload=new Update(new Objectives("Meta HTTP","","","",List.of(),List.of()),0L);mvc.perform(put("/api/employability-plan/objectives").header("Authorization","Bearer "+token).contentType(MediaType.APPLICATION_JSON).content(bridge.encode(payload))).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isOk()).andExpect(jsonPath("$.revision").value(1));for(var trail:List.of(TrailTokenService.Trail.EMPRESAS,TrailTokenService.Trail.CAPACITA)){var response=mvc.perform(get("/api/employability-plan").header("Authorization","Bearer "+tokens.issue(trail,u.email(),u.id(),0))).andReturn().getResponse();assertTrue(Set.of(401,403).contains(response.getStatus()));}var generated=mvc.perform(post("/api/employability-plan/refresh").header("Authorization","Bearer "+token).contentType(MediaType.APPLICATION_JSON).content(bridge.encode(new Refresh(1L,UUID.randomUUID())))).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isOk()).andExpect(jsonPath("$.generatedRevision").value(2)).andReturn();String key=bridge.read(generated.getResponse().getContentAsString()).path("plan").path("snapshot").path("steps").get(0).path("key").asText();mvc.perform(put("/api/employability-plan/steps/"+key).header("Authorization","Bearer "+token).contentType(MediaType.APPLICATION_JSON).content(bridge.encode(new Progress("IN_PROGRESS",2L)))).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isOk()).andExpect(jsonPath("$.revision").value(3));mvc.perform(get("/api/employability-plan/generations").header("Authorization","Bearer "+token)).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isOk()).andExpect(jsonPath("$.items.length()").value(1));mvc.perform(delete("/api/employability-plan").param("expectedRevision","3").header("Authorization","Bearer "+token)).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isNoContent());assertEquals(false,plans.get(u.email()).get("exists"));}

 @Test void trainingRemovedByTheSourceDisappearsOnRefreshWithoutDeletingItsAuditSnapshot(){var u=user();plans.update(u.email(),new Update(goal(job()),0L));generate(u);String key=steps(u).stream().filter(s->"TRAINING".equals(s.get("kind"))).findFirst().orElseThrow().get("key").toString();training.set("[]");generate(u);assertTrue(steps(u).stream().noneMatch(s->"TRAINING".equals(s.get("kind"))));status(404,()->plans.progress(u.email(),key,new Progress("DECLARED_DONE",revision(u))));assertEquals(2,rows(plans.history(u.email(),Long.MAX_VALUE,20).get("items")).size());}
 @Test void changedVacancyRequirementsAreReevaluatedByTheExistingRadar(){var u=user();long id=job();radar.declare(u.email(),new RadarService.Declaration("sql",2));plans.update(u.email(),new Update(goal(id),0L));generate(u);assertTrue(steps(u).stream().noneMatch(s->"SKILL_DEVELOPMENT".equals(s.get("kind"))));var next=new RadarModel.Requirements(2,List.of(new RadarModel.Need("sql",3,true,false,false)),null,null,false,false,"","","");jdbc.update("UPDATE radar_catalog_requirements SET revision=2,definition=?::jsonb WHERE item_id=?",bridge.encode(next),id);generate(u);assertTrue(steps(u).stream().anyMatch(s->"SKILL_DEVELOPMENT".equals(s.get("kind"))&&number(map(s.get("criteria")).get("requiredLevel"))==3));}
 @Test void objectivesValidateCatalogAndDoNotAcceptDuplicateReferences(){var u=user();status(400,()->plans.update(u.email(),new Update(new Objectives("Meta","","","",List.of(new SkillGoal("unknown-skill",1,false)),List.of()),0L)));status(400,()->plans.update(u.email(),new Update(new Objectives("Meta","","","",List.of(new SkillGoal("sql",1,false),new SkillGoal("sql",2,false)),List.of()),0L)));assertEquals(false,plans.get(u.email()).get("exists"));}

 @Test void concurrentObjectivesProgressAndRefreshUseOneLockOrder()throws Exception{
  var u=user();plans.update(u.email(),new Update(goal(job()),0L));generate(u);long expected=revision(u);String key=steps(u).getFirst().get("key").toString();var ready=new CountDownLatch(3);var start=new CountDownLatch(1);
  try(var pool=Executors.newFixedThreadPool(3)){
   List<Runnable> operations=List.of(()->plans.update(u.email(),new Update(new Objectives("Novo objetivo","","","",List.of(),List.of()),expected)),()->plans.progress(u.email(),key,new Progress("IN_PROGRESS",expected)),()->plans.refresh(u.email(),new Refresh(expected,UUID.randomUUID())));
   var futures=new ArrayList<Future<Integer>>();for(var operation:operations)futures.add(pool.submit(()->{ready.countDown();if(!start.await(5,TimeUnit.SECONDS))throw new IllegalStateException("Concurrent test start timeout");try{operation.run();return 200;}catch(ResponseStatusException error){return error.getStatusCode().value();}}));
   assertTrue(ready.await(5,TimeUnit.SECONDS));start.countDown();var statuses=new ArrayList<Integer>();for(var future:futures)statuses.add(future.get(15,TimeUnit.SECONDS));Collections.sort(statuses);assertEquals(List.of(200,409,409),statuses);assertEquals(expected+1,revision(u));
  }finally{start.countDown();}
 }

 @Test void concurrentDeleteAndProgressDoNotDeadlockOrLoseAnUpdate()throws Exception{
  for(int round=0;round<3;round++){
   var u=user();plans.update(u.email(),new Update(goal(job()),0L));generate(u);long expected=revision(u);String key=steps(u).getFirst().get("key").toString();var ready=new CountDownLatch(2);var start=new CountDownLatch(1);
   try(var pool=Executors.newFixedThreadPool(2)){
    List<Runnable> operations=List.of(()->plans.delete(u.email(),expected),()->plans.progress(u.email(),key,new Progress("IN_PROGRESS",expected)));
    var futures=new ArrayList<Future<Integer>>();for(var operation:operations)futures.add(pool.submit(()->{ready.countDown();if(!start.await(5,TimeUnit.SECONDS))throw new IllegalStateException("Concurrent test start timeout");try{operation.run();return 200;}catch(ResponseStatusException error){return error.getStatusCode().value();}}));
    assertTrue(ready.await(5,TimeUnit.SECONDS));start.countDown();var statuses=new ArrayList<Integer>();for(var future:futures)statuses.add(future.get(15,TimeUnit.SECONDS));assertEquals(1,Collections.frequency(statuses,200));assertTrue(statuses.stream().allMatch(code->Set.of(200,404,409).contains(code)));
    var plan=plans.get(u.email());if(Boolean.TRUE.equals(plan.get("exists"))){assertEquals(expected+1,revision(u));assertEquals("IN_PROGRESS",rows(plan.get("progress")).stream().filter(row->key.equals(row.get("step_key"))).findFirst().orElseThrow().get("state"));}else{assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM individual_employability_steps WHERE user_id=?",Integer.class,u.id()));assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM individual_employability_runs WHERE user_id=?",Integer.class,u.id()));}
   }finally{start.countDown();}
  }
 }
}
